#!/usr/bin/env bash
# atlas-commerce step setup (generated by scripts/atlas/compile_atlas.py; AUTHORING.md "Reset").
#
# Harbor uploads this step's workdir/ into /app and runs `bash /app/setup.sh` before the agent's
# turn. Code state "forward-merge-live": the tree becomes the base snapshot plus the reference
# changes of the tickets at earlier positions, and the live platform is rebuilt from that tree.
#   1. take the payload out of the repo and delete this script;
#   2. kill whatever the previous agent left running (process sweep, templates/lib_sweep.sh);
#   3. scrub grading material and the previous grader's scratch;
#   4. ask the controller (files on /run/atlas-ctl, this step's setup token) to reset the
#      platform: LocalStack, proxy and deny-guard restarted, Lambda containers removed, /shared
#      emptied, a new ProvisioningOperator key;
#   5. rebuild /app from /opt/odyssey/base.tar.gz (checked against the compiled manifest), apply
#      state.patch, keep the memory files, renew .git (one neutral commit);
#   6. deploy every component in the tree as the new ProvisioningOperator (deploy/deploy.py --all);
#   7. report the timings to the controller (collected by this step's verifier).
# Nothing here names the step's position or the ordering.
set -euo pipefail

# --- compile-time values -----------------------------------------------------
@@CONFIG@@

# --- container layout (overridable only so the script can be tested on a host) -
: "${ODYSSEY_BASE_TARBALL:=/opt/odyssey/base.tar.gz}"
: "${ODYSSEY_TESTS_DIR:=/tests}"
: "${ODYSSEY_SOLUTION_DIR:=/solution}"
: "${ODYSSEY_VERIFIER_DIR:=/logs/verifier}"
: "${ODYSSEY_SCRATCH_ROOT:=/tmp}"
: "${ODYSSEY_STOP_AGENTS:=1}"
: "${ODYSSEY_SWEEP_MATCH:=}"
: "${ATLAS_CTL_DIR:=/run/atlas-ctl}"
: "${ATLAS_GRADER_ROOT:=/var/lib/atlas-grader}"
: "${ATLAS_RESET_TIMEOUT_SEC:=420}"
: "${ATLAS_DEPLOY_TIMEOUT_SEC:=900}"
: "${ATLAS_PYTHON:=python3}"

SELF_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
SELF="$SELF_DIR/$(basename "${BASH_SOURCE[0]}")"
PAYLOAD_SRC="$SELF_DIR/.odyssey_step"
PAYLOAD=""
MEMORY_SAVE=""

export GIT_AUTHOR_NAME=Maintainers GIT_AUTHOR_EMAIL=maintainers@localhost
export GIT_COMMITTER_NAME=Maintainers GIT_COMMITTER_EMAIL=maintainers@localhost
export GIT_AUTHOR_DATE='2024-01-01T00:00:00+0000' GIT_COMMITTER_DATE='2024-01-01T00:00:00+0000'
export GIT_CONFIG_NOSYSTEM=1 GIT_CONFIG_GLOBAL=/dev/null

log() { printf '[atlas setup %s] %s\n' "$ODYSSEY_STEP" "$*" >&2; }
die() { log "ERROR: $*"; exit 1; }
now() { date +%s.%N; }
since() { awk -v a="$1" -v b="$(now)" 'BEGIN { printf "%.2f", b - a }'; }

git_() {
    git -c safe.directory='*' -c core.hooksPath=/dev/null -c core.fsmonitor=false \
        -c commit.gpgsign=false "$@"
}

cleanup() {
    if [ -n "$PAYLOAD" ]; then rm -rf "$PAYLOAD"; fi
    if [ -n "$MEMORY_SAVE" ]; then rm -rf "$MEMORY_SAVE"; fi
}
trap cleanup EXIT

take_payload() {
    PAYLOAD="$(mktemp -d "$ODYSSEY_SCRATCH_ROOT/odyssey-payload.XXXXXX")"
    if [ -d "$PAYLOAD_SRC" ]; then
        cp -a "$PAYLOAD_SRC/." "$PAYLOAD/"
        rm -rf "$PAYLOAD_SRC"
    fi
    rm -f "$SELF"
}

# --- process sweep (odyssey/templates/lib_sweep.sh) ------------------------------------
@@INCLUDE lib_sweep.sh@@

# --- controller requests (atlas/templates/lib_ctl.sh) ----------------------------------
@@INCLUDE lib_ctl.sh@@

scrub_outside_tree() {
    local dir
    for dir in "$ODYSSEY_TESTS_DIR" "$ODYSSEY_SOLUTION_DIR" "$ODYSSEY_VERIFIER_DIR"; do
        if [ -d "$dir" ]; then find "$dir" -mindepth 1 -maxdepth 1 -exec rm -rf {} + ; fi
    done
    rm -rf "$ODYSSEY_SCRATCH_ROOT"/odyssey-grade-* "$ATLAS_GRADER_ROOT"
    # Cached credentials of the previous step's keys (all revoked by the reset).
    rm -rf /root/.aws/cli/cache /root/.aws/boto/cache
}

save_memory_files() {
    MEMORY_SAVE="$(mktemp -d "$ODYSSEY_SCRATCH_ROOT/odyssey-memory.XXXXXX")"
    local f
    while IFS= read -r f; do
        [ -n "$f" ] || continue
        if [ -e "$ODYSSEY_WORKDIR/$f" ] || [ -L "$ODYSSEY_WORKDIR/$f" ]; then
            mkdir -p "$(dirname "$MEMORY_SAVE/$f")"
            cp -a "$ODYSSEY_WORKDIR/$f" "$MEMORY_SAVE/$f"
        fi
    done <<EOF
$ODYSSEY_MEMORY_FILES
EOF
}

restore_memory_files() {
    local f
    while IFS= read -r f; do
        [ -n "$f" ] || continue
        if [ -e "$MEMORY_SAVE/$f" ] || [ -L "$MEMORY_SAVE/$f" ]; then
            rm -rf "${ODYSSEY_WORKDIR:?}/$f"
            mkdir -p "$(dirname "$ODYSSEY_WORKDIR/$f")"
            cp -a "$MEMORY_SAVE/$f" "$ODYSSEY_WORKDIR/$f"
        fi
    done <<EOF
$ODYSSEY_MEMORY_FILES
EOF
}

# --- base snapshot manifest (odyssey/templates/lib_manifest.sh) ---------------------------
@@INCLUDE lib_manifest.sh@@

rebuild_tree() {
    [ -f "$ODYSSEY_BASE_TARBALL" ] || die "base snapshot $ODYSSEY_BASE_TARBALL not found (image contract)"
    find "$ODYSSEY_WORKDIR" -mindepth 1 -maxdepth 1 -exec rm -rf {} +
    tar -xzf "$ODYSSEY_BASE_TARBALL" -C "$ODYSSEY_WORKDIR"
    if [ -f "$PAYLOAD/base.manifest" ]; then
        tree_manifest "$ODYSSEY_WORKDIR" | cmp -s - "$PAYLOAD/base.manifest" \
            || die "base snapshot does not match the compiled manifest; refusing to start from a doctored tree"
    else
        log "no base manifest compiled in; base snapshot not verified"
    fi
}

fresh_repo() {
    rm -rf "${ODYSSEY_WORKDIR:?}/.git"
    (cd "$ODYSSEY_WORKDIR" && git_ -c init.defaultBranch=main init -q)
}

apply_state_patch() {
    local patch="$PAYLOAD/state.patch"
    [ -s "$patch" ] || return 0
    (cd "$ODYSSEY_WORKDIR" && git_ apply --check --whitespace=nowarn "$patch") \
        || die "state.patch does not apply to the base snapshot (tickets: $ODYSSEY_STATE_TICKETS)"
    (cd "$ODYSSEY_WORKDIR" && git_ apply --whitespace=nowarn "$patch")
}

commit_snapshot() {
    (cd "$ODYSSEY_WORKDIR" && git_ add -A && git_ commit -q --allow-empty --no-verify -m "Initial commit")
}

wait_builder() {
    # The new key must work through the proxy before anything is deployed with it.
    local i
    for i in $(seq 1 60); do
        if "$ATLAS_PYTHON" -I -B -c 'import boto3; boto3.client("sts").get_caller_identity()' >/dev/null 2>&1; then
            return 0
        fi
        sleep 1
    done
    die "the new ProvisioningOperator key did not work through the proxy within 60s"
}

deploy_platform() {
    local out="$PAYLOAD/deploy.log" attempt
    for attempt in 1 2; do
        if (cd "$ODYSSEY_WORKDIR" && PYTHONDONTWRITEBYTECODE=1 timeout "$ATLAS_DEPLOY_TIMEOUT_SEC" \
                "$ATLAS_PYTHON" -I -B deploy/deploy.py --all) > "$out" 2>&1; then
            DEPLOYED="$(grep -o '^\[deploy\] == [a-z0-9_]* done' "$out" | awk '{print $3}' | tr '\n' ' ')"
            return 0
        fi
        log "deploy attempt $attempt failed:"
        tail -n 30 "$out" >&2
    done
    die "deploying the platform from the repository failed"
}

main() {
    local t0 t_reset t_tree t_deploy reset_json
    [ -d "$ODYSSEY_WORKDIR" ] || die "workdir $ODYSSEY_WORKDIR does not exist"
    case "$ODYSSEY_WORKDIR" in /|/tmp|/var|/usr|/etc|/opt) die "refusing to reset system dir $ODYSSEY_WORKDIR";; esac
    t0="$(now)"
    take_payload
    sweep_processes
    scrub_outside_tree

    t_reset="$(now)"
    reset_json="$(ctl_request reset "$ATLAS_SETUP_TOKEN" "$ATLAS_RESET_TIMEOUT_SEC" '{}')" \
        || die "platform reset failed: $reset_json"
    RESET_SEC="$(since "$t_reset")"

    t_tree="$(now)"
    save_memory_files
    rebuild_tree
    fresh_repo
    apply_state_patch
    restore_memory_files
    commit_snapshot
    TREE_SEC="$(since "$t_tree")"

    t_deploy="$(now)"
    wait_builder
    DEPLOYED=""
    deploy_platform
    DEPLOY_SEC="$(since "$t_deploy")"

    mkdir -p "$ODYSSEY_MEMORY_DIR"
    if [ -f "$PAYLOAD/NOTES.md" ]; then cp "$PAYLOAD/NOTES.md" "$ODYSSEY_MEMORY_DIR/NOTES.md"; fi

    ctl_request setup-report "$ATLAS_SETUP_TOKEN" 60 \
        "{\"reset_sec\": $RESET_SEC, \"tree_sec\": $TREE_SEC, \"deploy_sec\": $DEPLOY_SEC, \"setup_sec\": $(since "$t0"), \"deployed\": \"${DEPLOYED% }\"}" \
        >/dev/null || log "warning: could not report timings"
    log "ready: reset ${RESET_SEC}s, tree ${TREE_SEC}s, deploy ${DEPLOY_SEC}s (${DEPLOYED% })"
}

main "$@"
